// Optional, offline geological context: reads the local package generated by pipelines/build_geology_context.py.
// The web app never calls SERNAGEOMIN, MMA or SIGAM; it only serves the file already included in the build.
import type { CandidateSite } from '../domain/contracts'
import { parseGeologyContext, type GeologyContextState } from '../domain/geologyContext'

/** The geological package v1 is tied to snapshot v3; another snapshot does not reuse it. */
export const GEOLOGY_CONTEXT_DIR = 'geology-context-v1'
export const GEOLOGY_TIMEOUT_MS = 8000
export const GEOLOGY_MAX_BYTES = 2 * 1024 * 1024

export function geologyContextUrl(baseUrl: string, file = 'index.json'): string {
  return `${baseUrl}${GEOLOGY_CONTEXT_DIR}/${file}`
}

type Fetcher = (input: string, init?: RequestInit) => Promise<Response>

/**
 * Never throws: if the package is missing, slow, too large or fails validation, it returns "not available" and the record,
 * the selection and M8 keep working. The maximum time covers reading the body, not just the header.
 */
export async function loadGeologyContext(
  candidates: CandidateSite[],
  options: { baseUrl?: string; fetcher?: Fetcher; timeoutMs?: number } = {},
): Promise<GeologyContextState> {
  const baseUrl = options.baseUrl ?? import.meta.env.BASE_URL
  const fetcher = options.fetcher ?? ((input, init) => fetch(input, init))
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? GEOLOGY_TIMEOUT_MS)
  try {
    const response = await fetcher(geologyContextUrl(baseUrl), { signal: controller.signal })
    if (!response.ok) {
      return { status: 'unavailable', reason: `The geology package for this version was not found.` }
    }
    const declared = Number(response.headers.get('content-length'))
    if (Number.isFinite(declared) && declared > GEOLOGY_MAX_BYTES) {
      return { status: 'unavailable', reason: 'The geology package exceeds the allowed size.' }
    }
    // The body is read under the same AbortController: a server that hangs midway through the response also times out.
    const text = await readBody(response, controller.signal)
    if (text.length > GEOLOGY_MAX_BYTES) {
      return { status: 'unavailable', reason: 'The geology package exceeds the allowed size.' }
    }
    return { status: 'ready', context: parseGeologyContext(JSON.parse(text) as unknown, candidates) }
  } catch {
    if (controller.signal.aborted) {
      return { status: 'unavailable', reason: 'The geological context took too long to load.' }
    }
    return {
      status: 'unavailable',
      reason: 'We could not verify the geology data for this version.',
    }
  } finally {
    clearTimeout(timer)
  }
}

/** Reads the body and rejects if the signal is aborted, even if the mocked Response does not observe it. */
function readBody(response: Response, signal: AbortSignal): Promise<string> {
  return new Promise<string>((resolve, reject) => {
    const onAbort = () => reject(new DOMException('abortado', 'AbortError'))
    if (signal.aborted) return onAbort()
    signal.addEventListener('abort', onAbort, { once: true })
    response.text().then(resolve, reject).finally(() => signal.removeEventListener('abort', onAbort))
  })
}
